-- ============================================================================
-- Remplacement complet du découpage territorial du Bénin
-- 12 départements / 77 communes / 546 arrondissements / 5304 quartiers
-- Source: server/config/decoupage_territorial.json
-- ATTENTION: ce script SUPPRIME le contenu actuel des 4 tables avant de le
-- remplacer par les données du JSON. Toute commune/quartier ajouté
-- manuellement depuis l'admin (hors JSON officiel) sera perdu.
-- ============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- Purge (ordre enfants -> parents)
DELETE FROM `quartiers`;
DELETE FROM `arrondissements`;
DELETE FROM `communes`;
DELETE FROM `departments`;

